CREATE DATABASE IF NOT EXISTS bd_citas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bd_citas;

CREATE TABLE IF NOT EXISTS pacientes (id INT AUTO_INCREMENT PRIMARY KEY, identificador VARCHAR(30) NOT NULL UNIQUE, nombre VARCHAR(160) NOT NULL, documento VARCHAR(40), telefono VARCHAR(40), email VARCHAR(160), creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS medicos (id INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(120) NOT NULL, especialidad VARCHAR(120) NOT NULL, consultorio VARCHAR(40) NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS turnos (id INT AUTO_INCREMENT PRIMARY KEY, medico_id INT NOT NULL, inicio DATETIME NOT NULL, fin DATETIME NOT NULL, estado ENUM('disponible','reservado','cancelado') NOT NULL DEFAULT 'disponible', UNIQUE KEY uq_turno_medico_inicio (medico_id, inicio), FOREIGN KEY (medico_id) REFERENCES medicos(id));
CREATE TABLE IF NOT EXISTS citas (id INT AUTO_INCREMENT PRIMARY KEY, paciente_id VARCHAR(30) NOT NULL, turno_id INT NULL, fecha_hora DATETIME NOT NULL, medico VARCHAR(120) NOT NULL, especialidad VARCHAR(120) NOT NULL, motivo VARCHAR(255), estado ENUM('reservada','confirmada','cancelada') NOT NULL DEFAULT 'reservada', creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, actualizado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (turno_id) REFERENCES turnos(id));
